   134  int fuzzer_init_php(const char *extra_ini)
   135  {
   136  #ifdef __SANITIZE_ADDRESS__
   137          /* We're going to leak all the memory allocated during startup,
   138           * so disable lsan temporarily. */
   139          __lsan_disable();
   140  #endif
   141
   142          sapi_startup(&fuzzer_module);
   143          fuzzer_module.phpinfo_as_text = 1;
   144
   145          size_t ini_len = sizeof(HARDCODED_INI);
   146          size_t extra_ini_len = extra_ini ? strlen(extra_ini) : 0;
   147          if (extra_ini) {
   148                  ini_len += extra_ini_len + 1;
   149          }
   150          char *p = fuzzer_module.ini_entries = malloc(ini_len + 1);
   151          memcpy(p, HARDCODED_INI, sizeof(HARDCODED_INI) - 1);
   152          p += sizeof(HARDCODED_INI) - 1;
   153          if (extra_ini) {
   154                  *p++ = '\n';
   155                  memcpy(p, extra_ini, extra_ini_len);
   156                  p += extra_ini_len;
   157          }
   158          *p = '\0';
   159
   160          /*
   161           * TODO: we might want to test both Zend and malloc MM, but testing with malloc
   162           * is more likely to find bugs, so use that for now.
   163           */
   164          putenv("USE_ZEND_ALLOC=0");
   165
   166          if (fuzzer_module.startup(&fuzzer_module)==FAILURE) {
   167                  return FAILURE;
